-- Estimates.
create function public.create_estimate_atomic(p_job_id uuid) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$begin if not private.has_permission('manage_estimates') then raise exception 'Permission denied'; end if; return public.create_estimate_atomic_impl(p_job_id); end$$;
create function public.add_estimate_option_atomic(p_estimate_id uuid,p_tier text,p_description text,p_price numeric,p_cost numeric,p_price_book_tier_id uuid) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$begin if not private.has_permission('manage_estimates') then raise exception 'Permission denied'; end if; return public.add_estimate_option_atomic_impl(p_estimate_id,p_tier,p_description,p_price,p_cost,p_price_book_tier_id); end$$;
