create function public.create_estimate_acceptance_link_atomic(p_estimate_id uuid) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$begin if not private.has_permission('manage_estimates') then raise exception 'Permission denied'; end if; return public.create_estimate_acceptance_link_atomic_impl(p_estimate_id); end$$;
create function public.revoke_estimate_acceptance_link_atomic(p_link_id uuid) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$begin if not private.has_permission('manage_estimates') then raise exception 'Permission denied'; end if; return public.revoke_estimate_acceptance_link_atomic_impl(p_link_id); end$$;

